PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS cath_pci_source_registry (source_id TEXT PRIMARY KEY,title TEXT NOT NULL,authority TEXT NOT NULL,url TEXT NOT NULL,effective_date TEXT,retrieved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,is_primary INTEGER NOT NULL DEFAULT 1 CHECK(is_primary IN(0,1)));
CREATE TABLE IF NOT EXISTS cath_pci_policy_versions (policy_id TEXT PRIMARY KEY,engine_version TEXT NOT NULL,effective_date TEXT NOT NULL,description TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cath_pci_code_catalog (code TEXT NOT NULL,system TEXT NOT NULL CHECK(system IN('CPT','HCPCS','ICD-10-PCS')),family TEXT NOT NULL,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',mue_value INTEGER,source_id TEXT NOT NULL REFERENCES cath_pci_source_registry(source_id),effective_date TEXT NOT NULL,PRIMARY KEY(code,system));
CREATE TABLE IF NOT EXISTS cath_pci_rule_catalog (rule_id TEXT PRIMARY KEY,policy_id TEXT NOT NULL REFERENCES cath_pci_policy_versions(policy_id),domain TEXT NOT NULL,condition_key TEXT NOT NULL,rule_summary TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES cath_pci_source_registry(source_id),disposition TEXT NOT NULL CHECK(disposition IN('hold','review','allow')));
CREATE TABLE IF NOT EXISTS cath_pci_cases (case_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,patient_reference TEXT,service_date TEXT,claim_scope TEXT NOT NULL,payer_type TEXT,payer_jurisdiction TEXT,status TEXT NOT NULL DEFAULT 'draft',engine_version TEXT NOT NULL,policy_version TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS cath_pci_cases_user_idx ON cath_pci_cases(user_id,created_at);
CREATE TABLE IF NOT EXISTS cath_pci_documents (document_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cath_pci_cases(case_id) ON DELETE CASCADE,object_key TEXT,file_name TEXT NOT NULL,sha256 TEXT NOT NULL,page_count INTEGER,extraction_method TEXT,requires_manual_review INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cath_pci_diagnostic_studies (study_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cath_pci_cases(case_id) ON DELETE CASCADE,right_heart_state TEXT,left_heart_state TEXT,coronary_angiography_state TEXT,graft_angiography_state TEXT,complete_study_state TEXT,medical_necessity_state TEXT,prior_study_available_state TEXT,prior_study_adequate_state TEXT,changed_condition_state TEXT,inadequate_visualization_state TEXT,clinical_change_state TEXT,decision_based_on_study_state TEXT,source_document_id TEXT REFERENCES cath_pci_documents(document_id));
CREATE TABLE IF NOT EXISTS cath_pci_interventions (intervention_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cath_pci_cases(case_id) ON DELETE CASCADE,vessel TEXT NOT NULL,artery_modifier TEXT,graft_label TEXT,lesions_treated INTEGER,stents_placed INTEGER,technique TEXT,device TEXT,approach TEXT,bifurcation_state TEXT,completed_state TEXT,source_verified_state TEXT,source_document_id TEXT REFERENCES cath_pci_documents(document_id));
CREATE TABLE IF NOT EXISTS cath_pci_adjuncts (adjunct_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cath_pci_cases(case_id) ON DELETE CASCADE,kind TEXT NOT NULL,vessel TEXT,artery_modifier TEXT,performed_state TEXT,source_verified_state TEXT,medical_necessity_state TEXT,source_document_id TEXT REFERENCES cath_pci_documents(document_id));
CREATE TABLE IF NOT EXISTS cath_pci_diagnosis_evidence (evidence_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cath_pci_cases(case_id) ON DELETE CASCADE,code TEXT NOT NULL,provider_documented_state TEXT NOT NULL DEFAULT 'unknown',clinically_supported_state TEXT NOT NULL DEFAULT 'unknown',source_document_id TEXT REFERENCES cath_pci_documents(document_id));
CREATE TABLE IF NOT EXISTS cath_pci_code_decisions (decision_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cath_pci_cases(case_id) ON DELETE CASCADE,code TEXT,system TEXT NOT NULL,role TEXT NOT NULL,status TEXT NOT NULL,rationale TEXT NOT NULL,modifiers_json TEXT NOT NULL DEFAULT '[]',blockers_json TEXT NOT NULL DEFAULT '[]',units INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cath_pci_ncci_results (result_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cath_pci_cases(case_id) ON DELETE CASCADE,edit_version TEXT NOT NULL,code_pair TEXT NOT NULL,result_json TEXT NOT NULL,checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cath_pci_approvals (approval_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cath_pci_cases(case_id) ON DELETE CASCADE,approver_user_id TEXT NOT NULL,action TEXT NOT NULL,attestation TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cath_pci_audit_events (event_id TEXT PRIMARY KEY,case_id TEXT REFERENCES cath_pci_cases(case_id) ON DELETE CASCADE,user_id TEXT NOT NULL,action TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

