INSERT OR REPLACE INTO cath_pci_rule_catalog(rule_id,policy_id,domain,condition_key,rule_summary,source_id,disposition) VALUES
('cath-inclusive-diagnostic','cath-pci-cms-2026q3','diagnostic','inclusive-family','Use one inclusive diagnostic cath family for documented components.','cms-cath-a52850','hold'),
('cath-same-session-gate','cath-pci-cms-2026q3','bundling','diagnostic-before-pci','Same-session diagnostic angiography is separate only when CMS diagnostic or justified-repeat criteria are documented.','cms-pci-a57479','hold'),
('pci-one-family-vessel','cath-pci-cms-2026q3','hierarchy','major-artery','Select one hierarchy-appropriate PCI family per major native artery or named graft.','cms-pci-a57479','hold'),
('pci-one-lesion-stent','cath-pci-cms-2026q3','lesion-count','92928','Use the current single-lesion stent family only when one treated lesion is documented.','cms-pci-a57479','hold'),
('pci-multiple-lesion-stent','cath-pci-cms-2026q3','lesion-count','92930','Use the 2026 multiple-lesion stent family only when two or more treated lesions are documented.','cms-pci-a57479','hold'),
('pci-retired-branches','cath-pci-cms-2026q3','code-status','2026-retired','Do not generate retired branch add-ons 92921, 92925, 92929, 92934, 92938, or 92944.','cms-pfs-rvu26c','hold'),
('pci-ami-one','cath-pci-cms-2026q3','mue','92941','The emergent AMI culprit intervention is limited to one unit per date of service.','cms-ncci-mue-2026q3','hold'),
('pci-cto-direction','cath-pci-cms-2026q3','technique','cto-direction','Distinguish antegrade-only CTO work from combined antegrade and retrograde work before selection.','cms-pci-a57479','hold'),
('pci-vessel-modifier','cath-pci-cms-2026q3','modifier','artery','Require source-verified LM, LD, LC, RC, or RI territory; never infer it.','cms-pci-a57479','hold'),
('pci-access-integral','cath-pci-cms-2026q3','bundling','access-imaging-closure','Access, catheter navigation, routine imaging, and closure are integral or packaged as applicable.','cms-pci-a57479','hold'),
('pci-thrombectomy','cath-pci-cms-2026q3','bundling','thrombectomy','Mechanical thrombectomy needs explicit evidence; aspiration is integral to AMI PCI and thrombectomy bundles with atherectomy.','cms-ncci-2026-xi','hold'),
('pci-adjunct-aoc','cath-pci-cms-2026q3','add-on','primary-code','Validate IVUS/OCT, physiology, thrombectomy, and brachytherapy against the current AOC file.','cms-ncci-aoc-2026q3','review'),
('pci-ncci-current','cath-pci-cms-2026q3','correct-coding','ptp-current','Check current practitioner or outpatient NCCI PTP edits for each combination.','cms-ncci-ptp-2026q3','review'),
('pci-pcs-independent','cath-pci-cms-2026q3','facility','no-cpt-crosswalk','Construct inpatient PCS independently from artery count, approach, device type/count, and bifurcation qualifier.','cms-icd10-pcs-2026','hold'),
('pci-outpatient-oce','cath-pci-cms-2026q3','facility','opps-oce','Hospital-outpatient candidates require current OPPS/OCE/APC review; do not estimate payment from professional logic.','cms-mcd-current','review'),
('pci-diagnosis-no-inference','cath-pci-cms-2026q3','diagnosis','provider-documented','Do not infer coronary disease, angina, infarction, graft disease, or complications from a procedure.','cms-ncci-2026-xi','hold'),
('pci-coverage-separate','cath-pci-cms-2026q3','coverage','payer-policy','Code selection does not establish coverage; verify date-effective payer/MAC policy and diagnosis support.','cms-mcd-current','review'),
('pci-human-release','cath-pci-cms-2026q3','safety','human-approval','Require human coder approval and disable autonomous claim submission.','cms-ncci-2026-xi','hold');
